// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }

    // Fuzzed parameters:
    // - bool shouldSucceed: controls whether the helper accepts the call (returns true) or reverts (returns false)
    // - address fromAddr: arbitrary from address forwarded as first arg to transfer
    // We do not fuzz the helper address because we deploy it here and pass its address to c.
    function testFuzz_property(bool shouldSucceed, address fromAddr) public {
        // keep fromAddr non-zero to be sensible
        if (fromAddr == address(0)) fromAddr = address(1);

        // Deploy a helper that exposes the exact signature transferFrom(address,address,uint256)
        // and either returns true (succeeds) or reverts based on shouldSucceed.
        Helper h = new Helper(shouldSucceed);

        // Prepare a single-recipient array so exactly one external call is made
        address[] memory tos = new address[](1);
        tos[0] = address(0xBEEF);
        uint[] memory vals = new uint[](1);
        vals[0] = 123;

        // Call c.transfer and observe whether it reverts or not via try/catch
        bool ok;
        try c.transfer(fromAddr, address(h), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assert): For the REFERENCE implementation,
        // when the helper is set to make the low-level call fail (shouldSucceed == false),
        // C.transfer must revert (ok == false); when the helper is set to succeed,
        // C.transfer must complete (ok == true).
        // The mutant inverts the success check and hence will violate this assertion for some inputs.
        assertTrue(ok == shouldSucceed);
    }
}

// Helper that matches the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
// It either returns (true) or reverts depending on its immutable flag.
contract Helper {
    bool public shouldSucceed;
    constructor(bool _shouldSucceed) { shouldSucceed = _shouldSucceed; }

    // Exact signature to be hit by abi.encodeWithSelector(id, from, _to, v)
    function transferFrom(address /*from*/, address /*to*/, uint256 /*v*/) external returns (bool) {
        if (shouldSucceed) {
            return true;
        }
        revert("helper revert");
    }
}
